this.loading = true;
this.error = null;
try {
  const items = await this.countriesApi.query.countries({}, { code: true, name: true, emoji: true });
  this.countries = items || [];
} catch (err) {
  this.error = (err && err.message) || 'Failed to load countries.';
} finally {
  this.loading = false;
}
